/**
 * Translate a bio-library term (crop / pest / disease / etc.) into the
 * current i18n language. Returns the original English string if the term
 * is not in the dictionary or the current language is English.
 */
export function translateBioTerm(englishName, lang) {
  if (!englishName || typeof englishName !== 'string') return englishName;
  // Normalize 'zh-CN' / 'pt-BR' style tags down to the base language
  const raw = lang || i18n.language || 'en';
  const code = String(raw).split('-')[0].toLowerCase();
  if (code === 'en') return englishName;
  const entry = BIO_TERMS[englishName];
  if (!entry) return englishName;
  return entry[code] || englishName;
}

export default translateBioTerm;
